SIM.kidney=stepper(i=>sv(600,300,'<ellipse cx="200" cy="110" rx="55" ry="80" fill="'+(i===0?'#e8a33d':'#c9786b')+'"/><ellipse cx="400" cy="110" rx="55" ry="80" fill="'+(i===0?'#e8a33d':'#c9786b')+'"/><path d="M220 180 L290 240 M380 180 L310 240" stroke="'+(i===1?'#e8a33d':'#d8c27a')+'" stroke-width="10"/><ellipse cx="300" cy="250" rx="45" ry="30" fill="'+(i===2?'#e8a33d':'#f0dc8a')+'"/><rect x="292" y="278" width="16" height="22" fill="'+(i===3?'#e8a33d':'#d8c27a')+'"/><text x="200" y="115" text-anchor="middle" style="'+T+'" font-size="16">كلية</text><text x="400" y="115" text-anchor="middle" style="'+T+'" font-size="16">كلية</text><text x="300" y="255" text-anchor="middle" style="'+T+'" font-size="14">المثانة</text><text x="120" y="230" style="'+T+'" font-size="14">الحالب</text>'),[['الكليتان','تنقّيان الدّم من الفضلات وتكوّنان البول.'],['الحالبان','أنبوبان ينقلان البول من الكليتين إلى المثانة.'],['المثانة','كيس عضليّ يخزّن البول مؤقّتًا.'],['مجرى البول','يخرج البول عبره إلى خارج الجسم.']]);
const MIT=[['الطّور التّمهيديّ','تتكثّف الكروموسومات وتظهر، ويختفي الغشاء النّوويّ.'],['الطّور الاستوائيّ','تصطفّ الكروموسومات في وسط الخليّة.'],['الطّور الانفصاليّ','تنفصل الكروماتيدات وتتّجه إلى قطبي الخليّة.'],['الطّور النّهائيّ','يتكوّن غشاء نوويّ حول كلّ مجموعة، وينقسم السّيتوبلازم فتنتج خليّتان متماثلتان.']];
SIM.mitosis=stepper(i=>{let b='<ellipse cx="300" cy="150" rx="'+(i===3?250:190)+'" ry="120" fill="#eef3e2" stroke="#647b43" stroke-width="4"/>';const X=(x,y,c)=>'<path d="M'+(x-8)+' '+(y-16)+' L'+(x+8)+' '+(y+16)+' M'+(x+8)+' '+(y-16)+' L'+(x-8)+' '+(y+16)+'" stroke="'+c+'" stroke-width="7" stroke-linecap="round"/>';
 if(i===0)b+=X(260,120,'#a24782')+X(330,170,'#2f7fb5')+X(300,110,'#e8a33d')+'<circle cx="300" cy="150" r="80" fill="none" stroke="#647b43" stroke-dasharray="8 8"/>';
 if(i===1)b+=X(300,95,'#a24782')+X(300,150,'#2f7fb5')+X(300,205,'#e8a33d')+'<path d="M130 150 L300 95 M130 150 L300 205 M470 150 L300 95 M470 150 L300 205" stroke="#bbb" />';
 if(i===2)[[95,'#a24782'],[150,'#2f7fb5'],[205,'#e8a33d']].forEach(([y,c])=>{b+='<path d="M200 '+y+' l-14 -10 M200 '+y+' l-14 10 M400 '+y+' l14 -10 M400 '+y+' l14 10" stroke="'+c+'" stroke-width="7" stroke-linecap="round"/>'});
 if(i===3)b+='<path d="M300 30 L300 270" stroke="#647b43" stroke-width="4"/><circle cx="170" cy="150" r="60" fill="#fff" stroke="#647b43" stroke-width="3"/><circle cx="430" cy="150" r="60" fill="#fff" stroke="#647b43" stroke-width="3"/>';return sv(600,300,b)},MIT);
SIM.earth=stepper(i=>{const L=[['القشرة','#a8743f'],['الوشاح','#e07b39'],['اللّبّ الخارجيّ','#f2b134'],['اللّبّ الدّاخليّ','#f7e07a']];let b='';L.forEach((l,k)=>{b+='<circle cx="300" cy="300" r="'+(270-k*65)+'" fill="'+l[1]+'" stroke="'+(i===k?'#2d3320':'none')+'" stroke-width="6"/>'});b+='<rect x="0" y="300" width="600" height="10" fill="#fbfaf4"/>';L.forEach((l,k)=>b+='<text x="300" y="'+(55+k*65)+'" text-anchor="middle" style="'+T+'" font-size="18" font-weight="'+(i===k?800:400)+'">'+l[0]+'</text>');return sv(600,305,b)},[['القشرة','الطّبقة الخارجيّة الصّلبة الّتي نعيش عليها، وهي أرقّ الطّبقات.'],['الوشاح','أسمك الطّبقات، صخوره شبه منصهرة في جزئه العلويّ.'],['اللّبّ الخارجيّ','طبقة سائلة من الحديد والنّيكل.'],['اللّبّ الدّاخليّ','كرة صلبة من الحديد والنّيكل، درجة حرارتها عالية جدًّا.']]);
SIM.fronts=stepper(i=>{const F=[['#2f7fb5','#e06b6b','باردة','دافئة'],['#e06b6b','#2f7fb5','دافئة','باردة'],['#2f7fb5','#2f7fb5','باردة','باردة']][i%3];return sv(600,260,'<path d="M0 230 H600" stroke="#7a6a4a" stroke-width="6"/><path d="'+(i===0?'M0 230 L0 60 C120 60 220 120 300 230 Z':i===1?'M600 230 L600 140 C450 140 360 190 300 230 Z':'M0 230 L0 70 C120 70 200 150 260 230 Z')+'" fill="'+F[0]+'" opacity=".55"/><path d="'+(i===0?'M300 230 C380 140 480 100 600 90 L600 230Z':i===1?'M0 90 C120 90 240 150 300 230 L0 230Z':'M600 230 L600 70 C480 70 400 150 340 230Z')+'" fill="'+F[1]+'" opacity=".45"/>'+(i<2?'<path d="M260 70 q20 -30 50 -10 q30 -20 50 10 q20 0 10 20 h-120 q-10 -20 10 -20z" fill="#fff" stroke="#999"/>':'')+'<text x="40" y="200" style="'+T+'" font-size="18">كتلة '+F[2]+'</text><text x="460" y="200" style="'+T+'" font-size="18">كتلة '+F[3]+'</text>')},[['الجبهة الباردة','تندفع كتلة هوائيّة باردة تحت كتلة دافئة فترفعها بسرعة، فتتكوّن غيوم ركاميّة وأمطار غزيرة قصيرة المدّة.'],['الجبهة الدّافئة','تتقدّم كتلة دافئة فوق كتلة باردة ببطء، فتتكوّن غيوم طبقيّة وأمطار خفيفة طويلة المدّة.'],['الجبهة المحتبسة','تلحق الجبهة الباردة بالدّافئة فترتفع الكتلة الدّافئة بينهما عن سطح الأرض.']]);
